<div class="status-summary"><div><strong><?= count($services) ?></strong><span>管理サイト</span></div><div><strong><?= count($attention) ?></strong><span>要対応・未確認</span></div><div><strong><?= count($migrations) ?></strong><span>移行の確認待ち</span></div></div>
